// Парсинг и валидация JSON-отчёта от агента (с level_summary)
const raw = $input.first().json.output || '';

function extractJson(text) {
  let t = String(text).trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) t = fence[1].trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('AGENT OUTPUT INVALID: JSON не найден');
  return JSON.parse(t.slice(start, end + 1));
}

const r = extractJson(raw);
if (!Array.isArray(r.srt_levels)) throw new Error('AGENT OUTPUT INVALID: нет srt_levels');

const today = new Date().toISOString().slice(0, 10);
r.date = r.date || today;
r.generated_at = new Date().toISOString();

const LEVEL_NAMES = { 9: 'Денежная система', 8: 'Институты спонтанного порядка', 7: 'Институты производства знаний', 6: 'Технологии производства знаний', 5: 'Экономическое разделение труда между фирмами', 4: '«Железные» технологии', 3: 'Социально-профессиональная структура', 2: 'Пространственная организация', 1: 'Природные ресурсы и география' };

const byLevel = {};
for (const lv of r.srt_levels) byLevel[lv.level] = lv;
r.srt_levels = [];
for (let l = 9; l >= 1; l--) {
  const src = byLevel[l] || {};
  const lv = { level: l, name: LEVEL_NAMES[l] };
  lv.level_summary = String(src.level_summary || '').trim();
  lv.events = (src.events || []).map(e => {
    const fact = (e.fact || e.description || '').trim();
    const why = (e.why_important || '').trim();
    return {
      title: (e.title || '').trim().replace(/^Факт:\s*/i, '').slice(0, 120),
      fact,
      why_important: why,
      description: why ? fact + ' Почему это важно: ' + why : fact,
      related_levels: Array.isArray(e.related_levels) ? e.related_levels : [],
      sources: (e.sources || []).filter(s => /^https?:\/\//.test(s))
    };
  }).filter(e => e.title && e.fact && e.sources.length > 0);
  lv.event_count = lv.events.length;
  r.srt_levels.push(lv);
}

const catOf = m => m >= 40 ? 'accelerating' : m >= 10 ? 'emerging' : m >= -9 ? 'stable' : m >= -39 ? 'decelerating' : 'collapsing';
r.trends = (r.trends || []).filter(t => t && t.name).map(t => {
  const m = Math.max(-100, Math.min(100, Math.round(Number(t.momentum) || 0)));
  return { id: t.id || null, name: String(t.name), momentum: m, category: catOf(m), rationale: t.rationale || '', levels: Array.isArray(t.levels) ? t.levels : [], is_new: !!t.is_new };
});
r.momentum_trends = r.trends;

r.structural_shifts = (r.structural_shifts || []).filter(s => s && s.title && s.from && s.to);
r.radar_signals = (r.radar_signals || []).filter(s => s && s.title);
r.cross_level_links = (r.cross_level_links || []).filter(c => c && c.title);
r.memory_notes = Array.isArray(r.memory_notes) ? r.memory_notes : [];

const totalEvents = r.srt_levels.reduce((s, l) => s + l.event_count, 0);
// Premature validation removed — Refill Gate handles minimum events, Validate Report blocks publication
// if (totalEvents < 5) — disabled, let refill cycle handle it
// Trends validation moved to Validate Report
// if (r.trends.length < 3) — disabled, let pipeline continue

const allSources = new Set();
r.srt_levels.forEach(l => l.events.forEach(e => e.sources.forEach(s => allSources.add(s))));
r.metrics = {
  total_events: totalEvents,
  structural_shifts_count: r.structural_shifts.length,
  radar_signals_count: r.radar_signals.length,
  cross_level_links_count: r.cross_level_links.length,
  trends_count: r.trends.length,
  total_sources: allSources.size
};

const reportJson = JSON.stringify(r, null, 2);
return [{ json: { report: r, reportJson, refill_iteration: 0 } }];

// Валидация отчёта (10 проверок) — без new URL (недоступен в сандбоксе)
const input = $input.first().json;
const report = input.report || {};
const errors = [];
const warnings = [];
const hostOf = u => { const m = String(u || '').match(/^https?:\/\/(?:www\.)?([^\/:?#]+)/i); return m ? m[1].toLowerCase() : null; };

// ─── 0. Входные данные агента ───
let inputCount = null; let inputStats = {};
try {
  const p = $('Prep Agent Input').first().json;
  inputCount = p.input_news_count;
  inputStats = p.input_source_stats || {};
} catch (e) { warnings.push('Нет телеметрии входа (Prep Agent Input)'); }
if (inputCount !== null) {
  if (inputCount < 15) errors.push(`На входе агента всего ${inputCount} новостей (минимум 15): ${JSON.stringify(inputStats)}`); // FIX: threshold 20→15
  if (Object.keys(inputStats).length < 3) errors.push(`Меньше 3 источников на входе: ${Object.keys(inputStats).join(', ')}`);
}

// ─── 1. Дата ───
const today = new Date().toISOString().slice(0, 10);
if (report.date !== today) errors.push(`Дата отчёта (${report.date}) не совпадает с сегодня (${today})`);

// ─── 2. Структура уровней + level_summary ───
const srtLevels = report.srt_levels || [];
if (srtLevels.length === 0) errors.push('srt_levels отсутствует или пуст');
const levelNums = new Set(srtLevels.map(l => l.level));
for (let l = 1; l <= 9; l++) {
  if (!levelNums.has(l)) errors.push(`Уровень ${l} отсутствует в структуре`);
}
for (const level of srtLevels) {
  if (!level.level_summary || !String(level.level_summary).trim()) warnings.push(`Уровень ${level.level}: нет level_summary`);
  const events = level.events || [];
  if (events.length === 0) { warnings.push(`Уровень ${level.level}: нет событий (допустимо)`); continue; }
  for (const event of events) {
    if (!event.title) errors.push(`Ур.${level.level}: событие без заголовка`);
    if (!event.sources || event.sources.length === 0) errors.push(`Ур.${level.level}, "${(event.title || '').slice(0, 40)}": нет источников`);
  }
}

// ─── 2б. Покрытие уровней ───
const levelsWithEvents = srtLevels.filter(l => (l.events || []).length > 0).length;
if (levelsWithEvents < 4) errors.push(`События только на ${levelsWithEvents} уровнях из 9 (минимум 4)`);
// Квота 3 события/уровень отменена (2026-07-21) — уровни могут быть пустыми, warning убран.

// ─── 3. Динамические блоки ───
for (const block of ['cross_level_links', 'structural_shifts', 'radar_signals']) {
  const val = report[block];
  if (!val) errors.push(`Блок "${block}" отсутствует`);
  else if (Array.isArray(val) && val.length === 0) warnings.push(`Блок "${block}" пуст`);
}

// ─── 4. trends (поле в отчёте — trends, не momentum_trends) ───
const momentum = report.trends || report.momentum_trends || [];
if (momentum.length === 0) {
  warnings.push('trends пуст (предупреждение, не ошибка)');
} else if (momentum.length < 3) {
  warnings.push(`Всего ${momentum.length} трендов`);
}

// ─── 5. Разнообразие источников ───
const allSources = [];
for (const level of srtLevels) for (const e of level.events || []) for (const s of e.sources || []) {
  if (typeof s === 'string' && /^https?:/.test(s)) { const h = hostOf(s); if (h) allSources.push(h); }
}
const uniqueDomains = [...new Set(allSources)];
if (uniqueDomains.length < 3 && allSources.length > 0) errors.push(`Только ${uniqueDomains.length} уникальных доменов (минимум 3): ${uniqueDomains.join(', ')}`);

// ─── 6. Проверка ссылок ───
const linksToCheck = [];
for (const level of srtLevels) for (const e of level.events || []) for (const s of e.sources || []) if (typeof s === 'string' && /^https?:/.test(s)) linksToCheck.push(s);
const sampleLinks = [...new Set(linksToCheck)].slice(0, 5);
const brokenLinks = [];
for (const url of sampleLinks) {
  try {
    const resp = await this.helpers.httpRequest({ method: 'HEAD', url, timeout: 5000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (resp.statusCode >= 400 && resp.statusCode !== 403 && resp.statusCode !== 405) brokenLinks.push(`${url} → HTTP ${resp.statusCode}`);
  } catch (e) { brokenLinks.push(`${url} → ${e.message}`); }
}
if (brokenLinks.length > 0) warnings.push(`Битые ссылки (${brokenLinks.length}/${sampleLinks.length}): ${brokenLinks.join('; ')}`);

// ─── 7. Метрики (адаптивный порог по времени суток) ───
const metrics = report.metrics || {};
/* Адаптивный порог: утро (08:00 UTC) — минимум 15, вечер (20:00 UTC) — минимум 25 */
const utcHourVal = new Date().getUTCHours();
const minEvents = (utcHourVal >= 16) ? 25 : 15;
const minLevels = (utcHourVal >= 16) ? 5 : 4;
const totalEventsVal = metrics.total_events || 0;
if (totalEventsVal < minEvents) {
  errors.push(`total_events = ${totalEventsVal} (минимум ${minEvents} для этого запуска)`);
}
const levelsWithEventsCheck = (report.srt_levels || []).filter(l => (l.events || []).length > 0).length;
if (levelsWithEventsCheck < minLevels) {
  errors.push(`События только на ${levelsWithEventsCheck} уровнях из 9 (минимум ${minLevels} для этого запуска)`);
}

// ─── 8. Языковая чистота ───
const ALLOW = new Set(['ai','ii','gpu','tpu','api','rlhf','dpo','moe','ssm','saas','capex','opex','llm','ml','it','hbm','etf','ipo','usd','arxiv','openai','google','alphabet','anthropic','microsoft','meta','nvidia','amazon','aws','deepmind','mistral','bloomberg','mit','sloan','gpt','claude','gemini','llama','grok','qwen','deepseek','hugging','face','github','softbank','oracle','apple','intel','amd','tsmc','samsung','sk','hynix','open-weight','open','weight','prompt','x','xai','techcrunch','register','dive','reuters','guardian','spacex','rwe','nato']);
let latin = 0, total = 0;
const texts = [];
for (const level of srtLevels) {
  texts.push(level.level_summary || '');
  for (const e of level.events || []) texts.push(e.title || '', e.fact || '', e.why_important || '');
}
for (const t of (report.trends || [])) texts.push(t.rationale || '');
for (const s of (report.structural_shifts || [])) texts.push(s.from || '', s.to || '', s.through || '');
for (const w of texts.join(' ').split(/\s+/)) {
  if (!w) continue;
  const lw = w.toLowerCase().replace(/[^a-zа-яё&-]/g, '');
  if (!lw) continue;
  total++;
  if (/^[a-z&-]{2,}$/.test(lw) && !ALLOW.has(lw)) latin++;
}
const latinShare = total ? latin / total : 0;
if (latinShare > 0.15) warnings.push(`Много английских слов: ${(latinShare * 100).toFixed(0)}% (порог 15%)`);

// ═══ ВЕРДИКТ ═══
const passed = errors.length === 0;
return [{
  json: {
    ...input,
    _validation: {
      passed, errors, warnings,
      checked_at: new Date().toISOString(),
      checks_run: 10,
      input_news_count: inputCount,
      input_sources: Object.keys(inputStats).length,
      levels_with_events: levelsWithEvents,
      latin_share: Math.round(latinShare * 100),
      sample_links_checked: sampleLinks.length,
      broken_links: brokenLinks.length,
      unique_sources: uniqueDomains.length
    }
  }
}];

// Мерж событий добора (AI Agent Refine) в текущий отчёт + инкремент итерации
const raw = ($input.first().json || {}).output || '';

// Текущее состояние отчёта — из последнего запуска Check Level Fill
const stateRuns = $('Check Level Fill').all();
const state = stateRuns[stateRuns.length - 1].json;
const report = JSON.parse(JSON.stringify(state.report));
const iteration = Number(state.refill_iteration || 0);

function extractJson(text) {
  let t = String(text).trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) t = fence[1].trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('REFINE OUTPUT INVALID: JSON не найден');
  return JSON.parse(t.slice(start, end + 1));
}

const normTitle = s => String(s || '').toLowerCase().replace(/[^a-zа-яё0-9 ]/gi, '').replace(/\s+/g, ' ').trim().slice(0, 120);

// Все уже известные заголовки (текущий отчёт + вчерашний отчёт)
const known = new Set();
for (const lv of report.srt_levels) for (const e of lv.events || []) known.add(normTitle(e.title));
for (const t of state.report && Array.isArray(state.previous_event_titles) ? state.previous_event_titles : []) known.add(normTitle(t));
try {
  const p = $('Prep Agent Input').first().json;
  for (const t of p.previous_event_titles || []) known.add(normTitle(t));
} catch (e) {}

let addedCount = 0;
let refineParseError = null;
try {
  const refined = extractJson(raw);
  const refinedLevels = Array.isArray(refined.srt_levels) ? refined.srt_levels : [];
  const byLevel = {};
  for (const lv of report.srt_levels) byLevel[lv.level] = lv;
  for (const rlv of refinedLevels) {
    const target = byLevel[rlv.level];
    if (!target) continue;
    for (const e of rlv.events || []) {
      const fact = String(e.fact || e.description || '').trim();
      const why = String(e.why_important || '').trim();
      const title = String(e.title || '').trim().replace(/^Факт:\s*/i, '').slice(0, 120);
      const sources = (e.sources || []).filter(s => typeof s === 'string' && /^https?:\/\//.test(s));
      if (!title || !fact || sources.length === 0) continue;
      const key = normTitle(title);
      if (!key || known.has(key)) continue;
      known.add(key);
      target.events.push({
        title,
        fact,
        why_important: why,
        description: why ? fact + ' Почему это важно: ' + why : fact,
        related_levels: Array.isArray(e.related_levels) ? e.related_levels : [],
        sources
      });
      addedCount++;
    }
  }
} catch (e) {
  refineParseError = String(e.message || e).slice(0, 200);
}

// Пересчёт метрик
for (const lv of report.srt_levels) lv.event_count = (lv.events || []).length;
const totalEvents = report.srt_levels.reduce((s, l) => s + l.event_count, 0);
const allSources = new Set();
report.srt_levels.forEach(l => l.events.forEach(e => e.sources.forEach(s => allSources.add(s))));
report.metrics = Object.assign({}, report.metrics, {
  total_events: totalEvents,
  total_sources: allSources.size,
  refill_iterations: iteration + 1,
  refill_added_events: (report.metrics && report.metrics.refill_added_events || 0) + addedCount
});

return [{ json: {
  report,
  reportJson: JSON.stringify(report, null, 2),
  refill_iteration: iteration + 1,
  _refill_added: addedCount,
  _refill_parse_error: refineParseError
} }];
